// Наполняем flow context стартовым набором, если он пуст.
const existing = flow.get("krupa_tasks");

if (Array.isArray(existing) && existing.length > 0) {
    return null;                    // не перетираем уже созданные задачи
}

flow.set("krupa_tasks", [
    { id: 1, title: "Прочитать методичку по Node-RED", done: true,  createdAt: "2026-01-01T09:00:00.000Z" },
    { id: 2, title: "Собрать поток inject → debug",    done: true,  createdAt: "2026-01-01T09:10:00.000Z" },
    { id: 3, title: "Сделать CRUD на http in/response", done: false, createdAt: "2026-01-01T09:20:00.000Z" }
]);

msg.payload = {
    student: "Крупа Ксения",
    message: "flow context krupa_tasks проинициализирован",
    count: 3
};
return msg;

function send(res, status, body) {
    res.statusCode = status;
    res.headers = { "Content-Type": "application/json; charset=utf-8" };
    res.payload = body;
    return res;
}

function badRequest(message, extra) {
    return {
        error: "Bad Request",
        message: message,
        student: "Крупа Ксения",
        extra: extra || null
    };
}

function notFound(id) {
    return {
        error: "Not Found",
        message: "Задача с id=" + id + " не найдена",
        student: "Крупа Ксения"
    };
}

function validateTitle(title) {
    if (typeof title !== "string") {
        return "Поле title обязательно и должно быть строкой";
    }
    const t = title.trim();
    if (t.length < 3 || t.length > 100) {
        return "Длина title должна быть от 3 до 100 символов";
    }
    return null;
}

const tasks = flow.get("krupa_tasks") || [];
const q = msg.req.query || {};

let result = tasks;
if (q.done !== undefined) {
    if (q.done !== "true" && q.done !== "false") {
        return send(msg, 400, badRequest("Параметр done должен быть true или false", { received: q.done }));
    }
    const wanted = q.done === "true";
    result = result.filter(function (t) { return t.done === wanted; });
}

return send(msg, 200, {
    student: "Крупа Ксения",
    lab: 2,
    total: tasks.length,
    count: result.length,
    tasks: result
});

