const body = msg.payload;

if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return send(msg, 400, badRequest("Тело запроса должно быть JSON-объектом"));
}

const titleError = validateTitle(body.title);
if (titleError) {
    return send(msg, 400, badRequest(titleError, { received: body.title }));
}

let done = false;
if (body.done !== undefined) {
    if (typeof body.done !== "boolean") {
        return send(msg, 400, badRequest("Поле done должно быть boolean", { received: body.done }));
    }
    done = body.done;
}

let maxId = 0;
for (const t of tasks) {
    if (t.id > maxId) { maxId = t.id; }
}

const task = {
    id: maxId + 1,
    title: body.title.trim(),
    done: done,
    createdAt: new Date().toISOString()
};

tasks.push(task);
flow.set("krupa_tasks", tasks);

return send(msg, 201, {
    student: "Крупа Ксения",
    message: "Задача создана",
    task: task,
    total: tasks.length
});

