}

const hasTitle = body.title !== undefined;
const hasDone = body.done !== undefined;

if (!hasTitle && !hasDone) {
    return send(msg, 400, badRequest("Нужно передать хотя бы одно поле: title или done"));
}

const updated = Object.assign({}, tasks[index]);

if (hasTitle) {
    const titleError = validateTitle(body.title);
    if (titleError) {
        return send(msg, 400, badRequest(titleError, { received: body.title }));
    }
    updated.title = body.title.trim();
}

if (hasDone) {
    if (typeof body.done !== "boolean") {
        return send(msg, 400, badRequest("Поле done должно быть boolean", { received: body.done }));
    }
    updated.done = body.done;
}

updated.updatedAt = new Date().toISOString();
tasks[index] = updated;
flow.set("krupa_tasks", tasks);

return send(msg, 200, {
    student: "Крупа Ксения",
    message: "Задача обновлена",
    task: updated
});

